const invoiceItems = $("Information Extractor").all();
const duplicateItems = $("Check Duplicate Invoice").all();

function cleanText(value) {
  return String(value ?? "").trim();
}

function parseAmount(value) {
  const cleaned = cleanText(value)
    .replace(/,/g, "")
    .replace(/[₦$€£]/g, "")
    .replace(/\s/g, "");

  if (cleaned === "") {
    return NaN;
  }

  return Number(cleaned);
}

function parseInvoiceDate(value) {
  const text = cleanText(value);

  if (!text) {
    return null;
  }

  const date = new Date(text);

  if (Number.isNaN(date.getTime())) {
    return null;
  }

  date.setHours(0, 0, 0, 0);
  return date;
}

return invoiceItems.map(item => {
  const extractedData = item.json.output || item.json;

  // Copy the extracted invoice information
  const data = { ...extractedData };

  // Make sure these fields always exist
  data["PO Number"] = data["PO Number"] || "";
  data["Payment Details"] = data["Payment Details"] || "";

  // Store every detected problem here
  const issues = [];

  // Required invoice fields
  const requiredFields = [
    "Vendor Name",
    "Invoice Number",
    "Invoice Date",
    "PO Number",
    "Due Date",
    "Currency",
    "Subtotal",
    "Tax",
    "Total Amount",
    "Payment Details"
  ];

  // Track specific types of problems
  let hasSeriousFinancialProblem = false;
  let hasDateProblem = false;

  // --------------------------------------------------
  // 1. Check for missing fields
  // --------------------------------------------------

  const missingFields = requiredFields.filter(field => {
    return cleanText(data[field]) === "";
  });

  if (missingFields.length > 0) {
    issues.push(
      "Missing invoice information: " +
      missingFields.join(", ") +
      "."
    );
  }

  // --------------------------------------------------
  // 2. Check the invoice amounts
  // --------------------------------------------------

  const subtotal = parseAmount(data["Subtotal"]);
  const tax = parseAmount(data["Tax"]);
  const totalAmount = parseAmount(data["Total Amount"]);

  if (!Number.isFinite(subtotal)) {
    issues.push("Subtotal is missing or not a valid number.");
    hasSeriousFinancialProblem = true;
  }

  if (!Number.isFinite(tax)) {
    issues.push("Tax is missing or not a valid number.");
    hasSeriousFinancialProblem = true;
  }

  if (!Number.isFinite(totalAmount)) {
    issues.push("Total Amount is missing or not a valid number.");
    hasSeriousFinancialProblem = true;
  }

  // Check for negative amounts
  if (Number.isFinite(subtotal) && subtotal < 0) {
    issues.push("Subtotal cannot be negative.");
    hasSeriousFinancialProblem = true;
  }

  if (Number.isFinite(tax) && tax < 0) {
    issues.push("Tax cannot be negative.");
    hasSeriousFinancialProblem = true;
  }

  if (Number.isFinite(totalAmount) && totalAmount < 0) {
    issues.push("Total Amount cannot be negative.");
    hasSeriousFinancialProblem = true;
  }

  // Check subtotal plus tax against total amount
  if (
    Number.isFinite(subtotal) &&
    Number.isFinite(tax) &&
    Number.isFinite(totalAmount)
  ) {
    const expectedTotal = subtotal + tax;
    const difference = Math.abs(expectedTotal - totalAmount);

    if (difference > 1) {
      issues.push(
        "Invoice total is incorrect. Expected " +
        expectedTotal +
        " but the invoice shows " +
        totalAmount +
        "."
      );

      hasSeriousFinancialProblem = true;
    }
  }

  // --------------------------------------------------
  // 3. Check the currency
  // --------------------------------------------------

  const currency = cleanText(data["Currency"]);

  if (currency === "") {
    issues.push("Currency is missing.");
  } else {
    const allowedCurrencies = [
      "NGN",
      "USD",
      "EUR",
      "GBP",
      "CAD",
      "AUD",
      "ZAR",
      "GHS",
      "KES"
    ];

    if (!allowedCurrencies.includes(currency.toUpperCase())) {
      issues.push(
        "Currency may be invalid or unsupported: " +
        currency +
        "."
      );
    }
  }

  // --------------------------------------------------
  // 4. Check invoice and due dates
  // --------------------------------------------------

  const invoiceDateText = cleanText(data["Invoice Date"]);
  const dueDateText = cleanText(data["Due Date"]);

  const invoiceDate = parseInvoiceDate(invoiceDateText);
  const dueDate = parseInvoiceDate(dueDateText);

  const today = new Date();
  today.setHours(0, 0, 0, 0);

  if (invoiceDateText !== "" && invoiceDate === null) {
    issues.push(
      "Invoice Date is invalid: " +
      invoiceDateText +
      "."
    );

    hasDateProblem = true;
  }

  if (dueDateText !== "" && dueDate === null) {
    issues.push(
      "Due Date is invalid: " +
      dueDateText +
      "."
    );

    hasDateProblem = true;
  }

  // Invoice date should not be after the due date
  if (invoiceDate !== null && dueDate !== null) {
    if (dueDate < invoiceDate) {
      issues.push(
        "Due Date is earlier than the Invoice Date."
      );

      hasDateProblem = true;
    }
  }

  // Invoice date should not be in the future
  if (invoiceDate !== null && invoiceDate > today) {
    issues.push(
      "Invoice Date is in the future."
    );

    hasDateProblem = true;
  }

  // Check whether the invoice is overdue
  if (dueDate !== null && dueDate < today) {
    issues.push(
      "Invoice is overdue because the Due Date has passed."
    );
  }

  // --------------------------------------------------
  // 5. Check the invoice number
  // --------------------------------------------------

  const currentInvoiceNumber = cleanText(
    data["Invoice Number"]
  );

  if (currentInvoiceNumber !== "") {
    const duplicateFound = duplicateItems.some(duplicateItem => {
      const duplicateData = duplicateItem.json || {};

      const existingInvoiceNumber = cleanText(
        duplicateData["Invoice Number"]
      );

      return (
        existingInvoiceNumber !== "" &&
        existingInvoiceNumber === currentInvoiceNumber
      );
    });

    if (duplicateFound) {
      issues.push(
        "Duplicate invoice number found in Google Sheets."
      );
    }

    data["Duplicate"] = duplicateFound ? "Yes" : "No";

    // Duplicate invoices are serious
    if (duplicateFound) {
      hasSeriousFinancialProblem = true;
    }
  } else {
    data["Duplicate"] = "No";
  }

  // --------------------------------------------------
  // 6. Check important text fields
  // --------------------------------------------------

  if (cleanText(data["Vendor Name"]) === "") {
    issues.push("Vendor Name is missing.");
  }

  if (cleanText(data["Invoice Number"]) === "") {
    issues.push("Invoice Number is missing.");
  }

  if (cleanText(data["PO Number"]) === "") {
    issues.push("PO Number is missing.");
  }

  if (cleanText(data["Payment Details"]) === "") {
    issues.push("Payment Details are missing.");
  }

  // --------------------------------------------------
  // 7. Decide the risk level
  // --------------------------------------------------

  let riskLevel = "Low";
  let validationStatus = "Passed";
  let approvalStatus = "Pending";

  if (hasSeriousFinancialProblem || hasDateProblem) {
    riskLevel = "High";
    validationStatus = "Failed";
    approvalStatus = "Rejected / Escalate";
  } else if (issues.length > 0) {
    riskLevel = "Medium";
    validationStatus = "Needs Review";
    approvalStatus = "Pending Review";
  }

  // --------------------------------------------------
  // 8. Create the complete Notes field
  // --------------------------------------------------

  let notes = "Invoice passed all basic validation checks.";

  if (issues.length > 0) {
    notes = issues.join(" ");
  }

  // --------------------------------------------------
  // 9. Generate Invoice ID
  // --------------------------------------------------

  const invoiceId =
    "INV-" +
    Date.now() +
    "-" +
    Math.random()
      .toString(36)
      .substring(2, 8)
      .toUpperCase();

  // --------------------------------------------------
  // 10. Nigeria processing date
  // --------------------------------------------------

  const processedDate = new Date()
    .toLocaleString("en-CA", {
      timeZone: "Africa/Lagos",
      year: "numeric",
      month: "2-digit",
      day: "2-digit",
      hour: "2-digit",
      minute: "2-digit",
      second: "2-digit",
      hour12: false
    })
    .replace(",", "");

  // --------------------------------------------------
  // 11. Add final fields
  // --------------------------------------------------

  data["Invoice ID"] = invoiceId;
  data["Risk Level"] = riskLevel;
  data["Validation Status"] = validationStatus;
  data["Approval Status"] = approvalStatus;
  data["Notes"] = notes;
  data["Processed Date"] = processedDate;

  return {
    json: data
  };
});
